/**
 * Codex adapter (stage 3): drives the user's OWN installed Codex through
 * `codex app-server` (stdio, newline-delimited JSON-RPC), the way T3 Code does.
 *
 * Prometheus is only the screen here. It sends `thread/start { cwd }` and the
 * user's text and optional explicitly selected model: no instructions, sandbox or approval policy,
 * so Codex's own login, config, tools and rules apply. Shapes come from the
 * protocol types generated by codex-cli 0.163.0 (`codex app-server generate-ts`).
 *
 * Never reads Codex auth files. Verification uses Codex's own `account/read`.
 */
import fs from 'fs';
import path from 'path';

import { JsonRpcStdioClient, type JsonRpcServerRequest } from '../jsonrpc-stdio';
import { compareVersions, readProgramVersion, resolveCodexCommand, type ResolvedCommand } from '../executable';
import { codexFileTouches } from '../file-touches';
import {
  sanitizeAgentText,
  type ExternalAgentAdapter,
  type ExternalAgentCapabilities,
  type ExternalAgentEvent,
  type ExternalAgentVerifyResult,
  type ExternalItemKind,
  type ExternalTurnInput,
  type ExternalTurnResult,
  type ExternalUserRequest,
  type ExternalUserResponse,
} from '../types';

/**
 * Oldest codex-cli this adapter accepts. The v2 thread/turn protocol it speaks
 * was read from 0.163.0; older builds are reported as too old rather than
 * driven with shapes nobody checked.
 */
export const CODEX_MIN_VERSION = '0.150.0';
export const CODEX_IDLE_SHUTDOWN_MS = 10 * 60_000;

export const CODEX_CAPABILITIES: ExternalAgentCapabilities = {
  resume: true,
  interrupt: true,
  approvals: true,
  images: false,
  modelList: true,
};

export interface CodexAdapterOptions {
  /** Injectable for tests: return a command that runs the fake app-server. */
  resolveCommand?: () => ResolvedCommand | null;
  readVersion?: (cmd: ResolvedCommand) => Promise<{ version: string; ok: boolean; error?: string }>;
  env?: NodeJS.ProcessEnv;
  idleMs?: number;
  clientVersion?: string;
  /** Tests: every JSON-RPC message Prometheus wrote to Codex. */
  onOutgoing?: (message: any) => void;
  /** Bound on control requests (initialize, account/read, thread/*, turn/start). */
  requestTimeoutMs?: number;
  /** After an interrupt, how long to wait for Codex's own turn/completed. */
  interruptGraceMs?: number;
}

type RequestUser = ExternalTurnInput['requestUser'];

/** One `codex app-server` process. It runs one turn at a time, so ending it can only end that turn. */
interface Runtime {
  client: JsonRpcStdioClient;
  /** Threads loaded in this process's memory. */
  threads: Set<string>;
  /** Claimed by a turn, from setup until it finishes. */
  reserved: boolean;
  /** A thread loaded here has since run in another process, so this copy is out of date: closed once its turn ends. */
  retire: boolean;
}

interface TurnContext {
  threadId: string;
  /** The process running this turn. */
  runtime: Runtime;
  turnId: string;
  emit: (event: ExternalAgentEvent) => void;
  requestUser: RequestUser;
  signal: AbortSignal;
  messageOrder: string[];
  messageText: Map<string, string>;
  outputTail: Map<string, string>;
  fileChangePaths: Map<string, string[]>;
  startedItems: Set<string>;
  /** Commands Codex started that have not finished. */
  runningCommands: Set<string>;
  /** Stop arrived while a command was running: the process is ended once Codex has recorded the stop. */
  endAfterStop: boolean;
  planCount: number;
  lastError: string;
  done: boolean;
  interruptSent: boolean;
  graceTimer: ReturnType<typeof setTimeout> | null;
  finish: (status: 'completed' | 'interrupted' | 'failed', error?: string) => void;
}

function readAppVersion(): string {
  try {
    const pkg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../../../package.json'), 'utf8')) as { version?: string };
    return String(pkg.version || 'unknown');
  } catch {
    return 'unknown';
  }
}

function short(value: unknown, max = 300): string {
  return String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
}

/**
 * Codex passes a provider's JSON error through as text. Show its message, not the JSON. A refused model
 * (Codex's own config can name one this Codex build may not use) also says what to do about it.
 */
export function plainCodexError(value: unknown): string {
  let text = String(value ?? '').trim();
  if (text.startsWith('{')) {
    try {
      const parsed = JSON.parse(text);
      const inner = parsed?.error?.message ?? parsed?.message;
      if (typeof inner === 'string' && inner.trim()) text = inner;
    } catch { /* not JSON after all */ }
  }
  text = short(text);
  return /\bmodel\b.*\bnot supported\b/i.test(text) ? `${text} Choose another model for this chat, or update Codex.` : text;
}

function tail(value: unknown, max = 400): string {
  const text = String(value ?? '').trim();
  return text.length > max ? `…${text.slice(-max)}` : text;
}

function planLabel(planType: unknown): string {
  const raw = short(planType, 40);
  if (!raw || raw === 'unknown') return 'ChatGPT';
  return `ChatGPT ${raw.charAt(0).toUpperCase()}${raw.slice(1)}`;
}

/** Codex error text when a stored thread id no longer exists. */
export function looksLikeMissingThread(message: string): boolean {
  return /not\s*found|no\s+such|unknown\s+thread|does\s+not\s+exist|no rollout|missing/i.test(String(message || ''));
}

export class CodexAdapter implements ExternalAgentAdapter {
  readonly id = 'codex' as const;
  readonly name = 'Codex';
  readonly tile = 'Cx';
  readonly capabilities = CODEX_CAPABILITIES;

  /**
   * Live app-server processes. Each runs one turn at a time: two chats working at once are in two
   * processes, so a forced stop of one never ends the other. One idle process is kept warm.
   */
  private runtimes = new Set<Runtime>();
  private starting: Promise<Runtime> | null = null;
  /** Forced stops in progress, by thread: that chat's next message waits until its old process is gone. */
  private stopping = new Map<string, Promise<boolean>>();
  /** App-servers whose forced stop could not be confirmed, by thread. */
  private stuck = new Map<string, JsonRpcStdioClient>();
  private turns = new Map<string, TurnContext>();
  private idleTimer: ReturnType<typeof setTimeout> | null = null;
  /** Turns still in setup (thread/start, thread/resume): no idle shutdown meanwhile. */
  private busy = 0;
  private readonly options: CodexAdapterOptions;

  constructor(options: CodexAdapterOptions = {}) {
    this.options = options;
  }

  private resolve(): ResolvedCommand | null {
    return (this.options.resolveCommand || (() => resolveCodexCommand(this.options.env || process.env)))();
  }

  private get timeoutMs(): number {
    return this.options.requestTimeoutMs ?? 30_000;
  }

  isRunning(): boolean {
    return [...this.runtimes].some((runtime) => runtime.client.alive);
  }

  /** Tests: pid of an app-server child (to prove no orphan after shutdown). */
  processId(): number | undefined {
    return this.processIds()[0];
  }

  /** Tests: pid of every live app-server child, oldest first. */
  processIds(): number[] {
    return [...this.runtimes].filter((runtime) => runtime.client.alive).map((runtime) => runtime.client.pid).filter((pid): pid is number => typeof pid === 'number');
  }

  activeTurnCount(): number {
    return this.turns.size + this.busy;
  }

  async detect(): Promise<{ found: boolean; executable?: string }> {
    const cmd = this.resolve();
    return cmd ? { found: true, executable: cmd.source } : { found: false };
  }

  /** Start one app-server and finish the handshake. */
  private async spawn(reserved: boolean): Promise<Runtime> {
    const cmd = this.resolve();
    if (!cmd) throw new Error("Codex isn't installed on this computer.");
    const client: JsonRpcStdioClient = new JsonRpcStdioClient({
      command: cmd.command,
      args: [...cmd.args, 'app-server'],
      env: this.options.env || process.env,
      label: 'Codex',
      onNotification: (method, params) => this.onNotification(runtime, method, params),
      onServerRequest: (request) => { void this.onServerRequest(runtime, request); },
      onExit: (info) => this.onExit(runtime, info.stderrTail),
      onOutgoing: this.options.onOutgoing,
    });
    const runtime: Runtime = { client, threads: new Set(), reserved, retire: false };
    try {
      await client.start();
      await client.request('initialize', {
        clientInfo: { name: 'prometheus', title: 'Prometheus', version: this.options.clientVersion || readAppVersion() },
        capabilities: { experimentalApi: false },
      }, this.timeoutMs);
      client.notify('initialized');
    } catch (error) {
      await client.stop(3000, { tree: true }).catch(() => undefined);
      throw error;
    }
    this.runtimes.add(runtime);
    return runtime;
  }

  /** A process for account, model and config questions: any live one, started when there is none. */
  private async controlClient(): Promise<JsonRpcStdioClient> {
    this.clearIdle();
    const live = [...this.runtimes].find((runtime) => runtime.client.alive && !runtime.retire);
    if (live) return live.client;
    if (!this.starting) this.starting = this.spawn(false).finally(() => { this.starting = null; });
    return (await this.starting).client;
  }

  /**
   * Claim a process for one turn: the chat's own when it is free, else another free one, else a new one.
   * A process never runs two turns, so ending one (a forced Stop) cannot reach another chat's work.
   */
  private async acquire(threadId: string): Promise<Runtime> {
    this.clearIdle();
    if (threadId) await this.waitForStop(threadId);
    const usable = (runtime: Runtime): boolean => runtime.client.alive && !runtime.retire;
    const home = threadId ? [...this.runtimes].find((runtime) => usable(runtime) && runtime.threads.has(threadId)) : undefined;
    let runtime = home && !home.reserved ? home : [...this.runtimes].find((candidate) => usable(candidate) && !candidate.reserved);
    if (runtime) runtime.reserved = true;
    else runtime = await this.spawn(true);
    // The chat moves on in another process, so the copy of it in its old one goes out of date.
    if (home && home !== runtime) home.retire = true;
    return runtime;
  }

  /** A forced stop of this chat's old process is still landing: nothing new starts for the chat until it is gone. */
  private async waitForStop(threadId: string): Promise<void> {
    const stopping = this.stopping.get(threadId);
    if (stopping) await stopping;
    const stuck = this.stuck.get(threadId);
    if (!stuck) return;
    const gone = await stuck.stop(3000, { tree: true }).catch(() => false);
    if (!gone) throw new Error('Codex did not stop when asked, so Prometheus will not start another one beside it. End the Codex process on this computer or restart Prometheus, then send the message again.');
    this.stuck.delete(threadId);
  }

  /** The turn is over: an out-of-date process closes, and so do spare idle ones. One idle process stays warm. */
  private release(runtime: Runtime): void {
    runtime.reserved = false;
    if (!this.runtimes.has(runtime)) return;
    if (runtime.retire || !runtime.client.alive) return this.close(runtime);
    // While something else is starting or asking a question, spare processes are left for it.
    if (this.busy > 0) return;
    for (const other of [...this.runtimes]) if (other !== runtime && !other.reserved) this.close(other);
  }

  /** Always the whole tree: a plain kill leaves the commands and helpers Codex started running. */
  private close(runtime: Runtime): void {
    this.runtimes.delete(runtime);
    void runtime.client.stop(3000, { tree: true }).catch(() => undefined);
  }

  private onExit(runtime: Runtime, stderrTail: string): void {
    // Closed or force-stopped on purpose: already taken out, and its turn already has its answer.
    if (!this.runtimes.delete(runtime)) return;
    const lines = String(stderrTail || '').split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
    const reason = short(lines[lines.length - 1] || 'Codex stopped unexpectedly.', 300);
    for (const ctx of [...this.turns.values()]) if (ctx.runtime === runtime) ctx.finish('failed', reason);
  }

  private clearIdle(): void {
    if (this.idleTimer) clearTimeout(this.idleTimer);
    this.idleTimer = null;
  }

  private scheduleIdle(): void {
    this.clearIdle();
    if (this.activeTurnCount() > 0 || !this.runtimes.size) return;
    const idleMs = this.options.idleMs ?? CODEX_IDLE_SHUTDOWN_MS;
    this.idleTimer = setTimeout(() => { void this.closeIdle(); }, idleMs);
    this.idleTimer.unref?.();
  }

  /** Stop every process when no turn is running. Returns true when they stopped (or none was running). */
  async closeIdle(): Promise<boolean> {
    if (this.activeTurnCount() > 0) return false;
    this.clearIdle();
    const all = [...this.runtimes];
    this.runtimes.clear();
    await Promise.all(all.map((runtime) => runtime.client.stop(3000, { tree: true }).catch(() => undefined)));
    return true;
  }

  private ctxFor(params: any, method = ''): TurnContext | null {
    const threadId = short(params?.threadId || params?.conversationId, 300);
    const ctx = threadId ? this.turns.get(threadId) : null;
    if (!ctx || ctx.done) return null;
    const turnId = short(params?.turnId || params?.turn?.id, 300);
    if (turnId && !ctx.turnId) {
      // Only `turn/started` (or the turn/start answer) names OUR turn. A resumed thread
      // replays notifications stamped with the PREVIOUS turn id (e.g. tokenUsage, a late
      // turn/completed); adopting those would drop every event of the real new turn.
      if (method !== 'turn/started') return null;
      this.adoptTurnId(ctx, turnId);
    }
    if (turnId && ctx.turnId && turnId !== ctx.turnId) return null;
    return ctx;
  }

  private adoptTurnId(ctx: TurnContext, turnId: string): void {
    if (!turnId || ctx.turnId === turnId) return;
    ctx.turnId = turnId;
    if (ctx.signal.aborted) this.interrupt(ctx);
  }

  private onNotification(runtime: Runtime, method: string, params: any): void {
    const ctx = this.ctxFor(params, method);
    // Only the process running a turn speaks for it.
    if (!ctx || ctx.runtime !== runtime) return;
    switch (method) {
      case 'turn/started':
        return;
      case 'item/agentMessage/delta': {
        const itemId = short(params?.itemId, 300) || '_';
        const delta = String(params?.delta ?? '');
        if (!delta) return;
        if (!ctx.messageText.has(itemId)) {
          if (ctx.messageOrder.length) ctx.emit({ type: 'text_delta', text: '\n\n' });
          ctx.messageOrder.push(itemId);
          ctx.messageText.set(itemId, '');
        }
        ctx.messageText.set(itemId, `${ctx.messageText.get(itemId) || ''}${delta}`);
        ctx.emit({ type: 'text_delta', text: delta });
        return;
      }
      case 'item/reasoning/summaryTextDelta':
      case 'item/reasoning/textDelta': {
        const delta = String(params?.delta ?? '');
        if (delta) ctx.emit({ type: 'reasoning_delta', text: delta });
        return;
      }
      case 'item/reasoning/summaryPartAdded':
        // A new section of the reasoning summary: keep the sections apart in the stream.
        if (Number(params?.summaryIndex) > 0) ctx.emit({ type: 'reasoning_delta', text: '\n\n' });
        return;
      case 'item/commandExecution/outputDelta': {
        const itemId = short(params?.itemId, 300);
        if (itemId) ctx.outputTail.set(itemId, `${ctx.outputTail.get(itemId) || ''}${String(params?.delta ?? '')}`.slice(-2000));
        return;
      }
      case 'item/started':
        this.onItem(ctx, params?.item, false);
        return;
      case 'item/completed':
        this.onItem(ctx, params?.item, true);
        return;
      case 'turn/plan/updated': {
        const steps = Array.isArray(params?.plan) ? params.plan : [];
        const lines = steps.slice(0, 20).map((step: any) => `${step?.status === 'completed' ? '[x]' : step?.status === 'inProgress' ? '[>]' : '[ ]'} ${short(step?.step, 200)}`);
        ctx.planCount += 1;
        const itemId = `plan-${ctx.planCount}`;
        ctx.emit({ type: 'item_started', itemId, kind: 'plan', title: 'Plan updated', detail: lines.join('\n') });
        ctx.emit({ type: 'item_completed', itemId, kind: 'plan', ok: true, summary: short(params?.explanation, 300) || `${steps.length} step(s)`, title: 'Plan updated' });
        return;
      }
      case 'thread/tokenUsage/updated': {
        const usage = params?.tokenUsage;
        const used = Number(usage?.last?.inputTokens ?? usage?.total?.totalTokens);
        const max = Number(usage?.modelContextWindow);
        ctx.emit({ type: 'usage', ...(Number.isFinite(used) ? { usedTokens: used } : {}), ...(Number.isFinite(max) && max > 0 ? { maxTokens: max } : {}) });
        return;
      }
      case 'error': {
        const message = plainCodexError(params?.error?.message || 'Codex reported an error.');
        ctx.lastError = message;
        if (params?.willRetry) ctx.emit({ type: 'notice', text: `Codex: ${message} (retrying)` });
        return;
      }
      case 'turn/completed': {
        const turn = params?.turn || {};
        const status = String(turn.status || 'completed');
        // Codex's final agentMessage items are authoritative over streamed deltas.
        for (const item of Array.isArray(turn.items) ? turn.items : []) {
          if (item?.type === 'agentMessage' && typeof item.text === 'string') this.recordMessage(ctx, item);
        }
        // Codex 0.163 on Windows confirms a stop while the command it started keeps running, so its process tree is ended too.
        if (status === 'interrupted') { if (ctx.endAfterStop) this.forceStop(ctx); else ctx.finish('interrupted'); }
        else if (status === 'failed') ctx.finish('failed', plainCodexError(turn.error?.message || ctx.lastError || 'Codex could not finish this turn.'));
        else ctx.finish('completed');
        return;
      }
      default:
        return;
    }
  }

  private recordMessage(ctx: TurnContext, item: any): void {
    const itemId = short(item?.id, 300) || '_';
    if (!ctx.messageText.has(itemId)) ctx.messageOrder.push(itemId);
    ctx.messageText.set(itemId, String(item.text));
  }

  /** Observed rows only. Prometheus never executes, replays or forwards these. */
  private onItem(ctx: TurnContext, item: any, completed: boolean): void {
    if (!item || typeof item !== 'object') return;
    const itemId = short(item.id, 300);
    if (!itemId) return;
    const type = String(item.type || '');
    if (type === 'agentMessage') {
      if (completed && typeof item.text === 'string') this.recordMessage(ctx, item);
      return;
    }
    if (type === 'userMessage' || type === 'reasoning' || type === 'hookPrompt' || type === 'contextCompaction') return;
    let kind: ExternalItemKind = 'other';
    let title = 'Codex step';
    let detail = '';
    let ok = true;
    let summary = '';
    let exitCode: number | undefined;
    if (type === 'commandExecution') {
      kind = 'command';
      title = 'Ran a command';
      if (completed) {
        ctx.runningCommands.delete(itemId);
      } else {
        ctx.runningCommands.add(itemId);
        // Stop was already asked for when this command's start arrived: it counts as running at Stop.
        if (ctx.graceTimer) ctx.endAfterStop = true;
      }
      detail = short(item.command, 2000);
      exitCode = Number.isFinite(Number(item.exitCode)) && item.exitCode !== null ? Number(item.exitCode) : undefined;
      ok = !['failed', 'declined'].includes(String(item.status)) && (exitCode === undefined || exitCode === 0);
      summary = tail(item.aggregatedOutput ?? ctx.outputTail.get(itemId) ?? '') || (ok ? 'Done' : `Status: ${short(item.status, 40)}`);
    } else if (type === 'fileChange') {
      kind = 'file_change';
      const files = (Array.isArray(item.changes) ? item.changes : []).map((change: any) => short(change?.path, 400)).filter(Boolean);
      if (files.length) ctx.fileChangePaths.set(itemId, files);
      title = files.length === 1 ? 'Changed a file' : `Changed ${files.length || 'some'} files`;
      detail = files.slice(0, 20).join('\n');
      ok = !['failed', 'declined'].includes(String(item.status));
      summary = ok ? (files.slice(0, 5).join(', ') || 'Done') : `Status: ${short(item.status, 40)}`;
      // What Codex reports it applied builds the end-of-turn file card.
      if (completed && ok) ctx.emit({ type: 'file_change', files: codexFileTouches(item) });
    } else if (type === 'mcpToolCall' || type === 'dynamicToolCall') {
      kind = 'mcp_tool';
      title = `Used ${short([item.server || item.namespace, item.tool].filter(Boolean).join(' / '), 120) || 'a tool'}`;
      ok = String(item.status) !== 'failed' && !item.error && item.success !== false;
      summary = ok ? 'Done' : short(item.error?.message || 'Failed', 300);
    } else if (type === 'webSearch') {
      kind = 'web_search';
      title = 'Searched the web';
      detail = short(item.query, 300);
      summary = detail || 'Done';
    } else if (type === 'plan') {
      kind = 'plan';
      title = 'Plan';
      detail = short(item.text, 2000);
      summary = 'Plan';
    } else {
      title = `Codex: ${short(type, 60) || 'step'}`;
      summary = 'Done';
    }
    if (!completed) {
      if (ctx.startedItems.has(itemId)) return;
      ctx.startedItems.add(itemId);
      ctx.emit({ type: 'item_started', itemId, kind, title, ...(detail ? { detail } : {}) });
      return;
    }
    if (!ctx.startedItems.has(itemId)) {
      ctx.startedItems.add(itemId);
      ctx.emit({ type: 'item_started', itemId, kind, title, ...(detail ? { detail } : {}) });
    }
    ctx.emit({ type: 'item_completed', itemId, kind, ok, summary, title, ...(exitCode !== undefined ? { exitCode } : {}) });
  }

  /** Codex's own approval/question requests. The answer goes back to THIS JSON-RPC id only. */
  private async onServerRequest(runtime: Runtime, request: JsonRpcServerRequest): Promise<void> {
    const client = runtime.client;
    const params = request.params || {};
    const ctx = this.ctxFor(params);
    if (!ctx || ctx.runtime !== runtime) {
      // No live turn owns it (stale or foreign): never leave Codex hanging.
      client.respondError(request.id, -32601, 'Prometheus has no open turn for this request.');
      return;
    }
    const mapped = mapCodexServerRequest(request.method, params, ctx.fileChangePaths);
    if (!mapped) {
      ctx.emit({ type: 'notice', text: `Codex asked for something Prometheus can't show yet (${short(request.method, 80)}). It was declined.` });
      client.respondError(request.id, -32601, `Prometheus does not support ${short(request.method, 80)}.`);
      return;
    }
    try {
      const answer = await ctx.requestUser(mapped.card, { signal: ctx.signal, cancelResponse: { optionId: mapped.cancelOptionId } });
      client.respond(request.id, mapped.toResult(answer));
    } catch (error: any) {
      client.respond(request.id, mapped.toResult({ optionId: mapped.cancelOptionId }));
    }
  }

  /** Codex's own status path: `--version`, then `account/read` through app-server. Never reads auth files. */
  async verify(): Promise<ExternalAgentVerifyResult> {
    const capabilities = CODEX_CAPABILITIES;
    const cmd = this.resolve();
    if (!cmd) {
      return {
        status: 'not_installed',
        statusText: "Codex isn't installed on this computer.",
        fixHint: 'Install Codex yourself, then Check again.',
        capabilities,
      };
    }
    const read = await (this.options.readVersion || readProgramVersion)(cmd);
    const version = read.version || undefined;
    if (!read.ok) {
      return { status: 'error', statusText: `Couldn't start Codex: ${short(read.error || 'no answer', 160)}. Check again`, capabilities };
    }
    if (version && compareVersions(version, CODEX_MIN_VERSION) < 0) {
      return {
        status: 'too_old',
        statusText: `Codex ${version} is too old. Update Codex to ${CODEX_MIN_VERSION} or newer, then Check again`,
        fixHint: 'Update Codex yourself (for example `npm i -g @openai/codex`), then Check again.',
        version,
        capabilities,
      };
    }
    this.busy += 1;
    try {
      const client = await this.controlClient();
      const res: any = await client.request('account/read', { refreshToken: false }, this.timeoutMs);
      const account = res?.account && typeof res.account === 'object' ? res.account : null;
      if (!account && res?.requiresOpenaiAuth !== false) {
        return {
          status: 'signed_out',
          statusText: 'Not signed in. Run `codex login` in a terminal, then Check again',
          fixHint: 'Run `codex login` in a terminal, then Check again.',
          ...(version ? { version } : {}),
          capabilities,
        };
      }
      const kind = account ? short(account.type, 40) || 'unknown' : 'provider';
      const label = kind === 'chatgpt'
        ? planLabel(account?.planType)
        : kind === 'apiKey' ? 'API key' : kind === 'amazonBedrock' ? 'Amazon Bedrock' : 'Own model provider';
      return {
        status: 'ready',
        statusText: ['Connected', version ? `v${version}` : '', label].filter(Boolean).join(' · '),
        ...(version ? { version } : {}),
        // Never the email, never a token: only the sign-in kind and plan label.
        account: { kind, label },
        capabilities,
      };
    } catch (error: any) {
      return {
        status: 'error',
        statusText: `Couldn't start Codex: ${short(error?.message || error, 160)}. Check again`,
        ...(version ? { version } : {}),
        capabilities,
      };
    } finally {
      this.busy -= 1;
      this.scheduleIdle();
    }
  }

  async listModels(context: { cwd: string }) {
    this.busy += 1;
    try {
      const client = await this.controlClient();
      const models: Array<{ id: string; label: string; efforts: string[]; isDefault: boolean }> = [];
      let cursor: string | undefined;
      for (let page = 0; page < 10; page++) {
        const response = await client.request('model/list', { limit: 100, ...(cursor ? { cursor } : {}) }, this.timeoutMs);
        for (const item of response?.data || []) if (!item.hidden && typeof item.model === 'string') models.push({ id: item.model, label: String(item.displayName || item.model), efforts: (item.supportedReasoningEfforts || []).map((e: { reasoningEffort: string }) => e.reasoningEffort), isDefault: item.isDefault === true });
        cursor = response?.nextCursor || undefined;
        if (!cursor) break;
      }
      const config = await client.request('config/read', { cwd: context.cwd, includeLayers: false }, this.timeoutMs);
      return { models, ...(typeof config?.config?.model === 'string' ? { currentModel: config.config.model } : {}) };
    } finally { this.busy -= 1; this.scheduleIdle(); }
  }

  async runTurn(input: ExternalTurnInput): Promise<ExternalTurnResult> {
    this.busy += 1;
    let threadId = String(input.upstreamSessionId || '').trim();
    let model: string | undefined = input.model;
    let runtime: Runtime | undefined;
    try {
      if (threadId && this.turns.has(threadId)) {
        return { upstreamSessionId: threadId, status: 'failed', finalText: '', error: 'Codex is still working on the previous message.' };
      }
      const held = await this.acquire(threadId);
      runtime = held;
      const client = held.client;
      if (input.signal.aborted) return { upstreamSessionId: threadId, status: 'interrupted', finalText: '' };
      if (!threadId) {
        input.emit({ type: 'state', phase: 'starting' });
        // ONLY cwd: Codex's own model, approval policy, sandbox and instructions apply.
        const res: any = await client.request('thread/start', { cwd: input.cwd }, this.timeoutMs);
        threadId = short(res?.thread?.id, 300);
        if (!threadId) throw new Error('Codex did not return a session id.');
        model = input.model || short(res?.model, 120) || undefined;
        held.threads.add(threadId);
      } else if (!held.threads.has(threadId)) {
        input.emit({ type: 'state', phase: 'resuming' });
        try {
          const res: any = await client.request('thread/resume', { threadId, excludeTurns: true }, this.timeoutMs);
          model = input.model || short(res?.model, 120) || undefined;
          held.threads.add(threadId);
        } catch (error: any) {
          const message = short(error?.message || error);
          if (looksLikeMissingThread(message)) {
            return { upstreamSessionId: threadId, status: 'failed', finalText: '', error: "Codex can't find this session any more.", upstreamMissing: true };
          }
          throw error;
        }
      }
      input.onSessionBound?.(threadId);
      if (input.signal.aborted) return { upstreamSessionId: threadId, status: 'interrupted', finalText: '' };
      input.emit({ type: 'state', phase: 'running' });
      const text = sanitizeAgentText(input.text);
      const first = await this.sendTurn(input, held, threadId, text, { startModel: input.model, reportModel: model });
      // Codex's own configured model can be one this Codex build refuses. Retry once, in the same thread, with a model
      // Codex lists, but only when the user has not picked a model and nothing from this attempt reached them.
      if (input.model || first.result.status !== 'failed' || first.touched || input.signal.aborted || !/\bmodel\b.*\bnot supported\b/i.test(first.result.error || '')) return first.result;
      const fallback = await this.listedFallbackModel(input.cwd);
      if (!fallback) return first.result;
      input.emit({ type: 'notice', text: `Codex's configured model isn't available in this Codex version, so this chat is using ${fallback.label}. Update Codex or pick a model to change it.` });
      const retry = await this.sendTurn(input, held, threadId, text, { startModel: fallback.id, reportModel: fallback.id });
      if (retry.result.status === 'failed') return first.result;
      return retry.result.status === 'completed' ? { ...retry.result, fallbackModel: fallback.id } : retry.result;
    } catch (error: any) {
      return {
        upstreamSessionId: threadId,
        status: input.signal.aborted ? 'interrupted' : 'failed',
        finalText: '',
        error: short(error?.message || error),
        ...(model ? { model } : {}),
      };
    } finally {
      this.busy -= 1;
      if (runtime) this.release(runtime);
      this.scheduleIdle();
    }
  }

  /** The model Codex marks as its default, else the first one listed. Undefined when the list is empty or unreadable. */
  private async listedFallbackModel(cwd: string): Promise<{ id: string; label: string } | undefined> {
    try {
      const catalog = await this.listModels({ cwd });
      const entry = catalog.models.find((item) => item.isDefault) || catalog.models[0];
      return entry ? { id: entry.id, label: entry.label } : undefined;
    } catch {
      return undefined;
    }
  }

  /**
   * One turn/start on an already bound thread. `touched` becomes true once anything from this attempt
   * reached the user (text, reasoning, an item, or a request for the user), which rules out a silent retry.
   */
  private sendTurn(
    input: ExternalTurnInput,
    held: Runtime,
    threadId: string,
    text: string,
    models: { startModel?: string; reportModel?: string },
  ): Promise<{ result: ExternalTurnResult; touched: boolean }> {
    let touched = false;
    const boundThreadId = threadId;
    return new Promise((resolve) => {
      const requestLifetime = new AbortController();
      const onAbort = () => { requestLifetime.abort(); this.interrupt(ctx); };
      const ctx: TurnContext = {
        threadId: boundThreadId,
        runtime: held,
        turnId: '',
        emit: (event) => {
          if (event.type === 'text_delta' || event.type === 'reasoning_delta' || event.type === 'item_started' || event.type === 'item_completed') touched = true;
          input.emit(event);
        },
        requestUser: (...args: Parameters<ExternalTurnInput['requestUser']>) => {
          touched = true;
          return input.requestUser(...args);
        },
        signal: requestLifetime.signal,
        messageOrder: [],
        messageText: new Map(),
        outputTail: new Map(),
        fileChangePaths: new Map(),
        startedItems: new Set(),
        runningCommands: new Set(),
        endAfterStop: false,
        planCount: 0,
        lastError: '',
        done: false,
        interruptSent: false,
        graceTimer: null,
        finish: (status, error) => {
          if (ctx.done) return;
          ctx.done = true;
          requestLifetime.abort();
          if (ctx.graceTimer) clearTimeout(ctx.graceTimer);
          this.turns.delete(boundThreadId);
          input.signal.removeEventListener('abort', onAbort);
          resolve({
            touched,
            result: {
              upstreamSessionId: boundThreadId,
              ...(ctx.turnId ? { upstreamTurnId: ctx.turnId } : {}),
              status,
              finalText: this.finalText(ctx),
              ...(error ? { error: short(error) } : {}),
              ...(models.reportModel ? { model: models.reportModel } : {}),
            },
          });
        },
      };
      this.turns.set(boundThreadId, ctx);
      input.signal.addEventListener('abort', onAbort, { once: true });
      held.client.request('turn/start', { threadId: boundThreadId, ...(models.startModel ? { model: models.startModel } : {}), ...(input.effort ? { effort: input.effort } : {}), input: [{ type: 'text', text, text_elements: [] }] }, this.timeoutMs)
        .then((res: any) => {
          // The turn/start answer is authoritative for which turn is ours.
          const turnId = short(res?.turn?.id, 300);
          if (turnId && !ctx.done) this.adoptTurnId(ctx, turnId);
          if (input.signal.aborted) this.interrupt(ctx);
        })
        .catch((error: any) => ctx.finish(input.signal.aborted ? 'interrupted' : 'failed', short(error?.message || error)));
      if (input.signal.aborted) onAbort();
    });
  }


  /**
   * Stop: `turn/interrupt` to Codex, keep what streamed, wait briefly for Codex's own turn/completed.
   * Stop has to mean stopped. If Codex refuses the interrupt or never confirms it, the app-server may
   * still be running commands, so the process is ended instead of only marking the turn as stopped.
   */
  private interrupt(ctx: TurnContext): void {
    if (ctx.done) return;
    if (ctx.runningCommands.size) ctx.endAfterStop = true;
    if (!ctx.graceTimer) {
      ctx.graceTimer = setTimeout(() => this.forceStop(ctx), this.options.interruptGraceMs ?? 5_000);
    }
    if (ctx.interruptSent || !ctx.turnId) return; // turnId arrives with the turn/start answer; retried there.
    ctx.interruptSent = true;
    ctx.runtime.client.request('turn/interrupt', { threadId: ctx.threadId, turnId: ctx.turnId }, 10_000).catch(() => this.forceStop(ctx));
  }

  /**
   * Codex did not confirm the stop, or confirmed it with a command still running: end this chat's app-server
   * and everything it started, so nothing keeps running behind a chat that says "Stopped". No other chat's
   * turn runs in that process, so only the stopped chat is affected. Its thread is on disk and resumes in a new one.
   */
  private forceStop(ctx: TurnContext): void {
    if (ctx.done) return;
    const client = ctx.runtime.client;
    const threadId = ctx.threadId;
    // Taken out first: nothing else is ever started on a process that is being ended.
    this.runtimes.delete(ctx.runtime);
    // The commands Codex started go with it, and this chat's next message waits until the old process is confirmed gone.
    const stopping: Promise<boolean> = client.stop(3000, { tree: true }).catch(() => false).then((gone) => {
      if (!gone) this.stuck.set(threadId, client);
      if (this.stopping.get(threadId) === stopping) this.stopping.delete(threadId);
      return gone;
    });
    this.stopping.set(threadId, stopping);
    ctx.finish('interrupted');
  }

  private finalText(ctx: TurnContext): string {
    return ctx.messageOrder.map((id) => (ctx.messageText.get(id) || '').trim()).filter(Boolean).join('\n\n');
  }

  async shutdown(): Promise<void> {
    this.clearIdle();
    for (const ctx of [...this.turns.values()]) ctx.finish('interrupted', 'Prometheus is shutting down.');
    const all = [...this.runtimes];
    this.runtimes.clear();
    await Promise.all(all.map((runtime) => runtime.client.stop(3000, { tree: true }).catch(() => undefined)));
  }
}

type CardInput = Omit<ExternalUserRequest, 'requestId' | 'agentId' | 'sessionId'>;

export interface MappedCodexRequest {
  card: CardInput;
  /** What Codex is told when the turn is stopped before the user answers. */
  cancelOptionId: string;
  /** The exact JSON-RPC result for this request's own response type. */
  toResult: (answer: ExternalUserResponse) => any;
}

const V2_DECISION_OPTIONS: CardInput['options'] = [
  { id: 'accept', label: 'Allow once', kind: 'allow_once' },
  { id: 'acceptForSession', label: 'Allow for this Codex session', kind: 'allow_session' },
  { id: 'decline', label: 'Decline', kind: 'deny' },
  { id: 'cancel', label: 'Decline and stop', kind: 'cancel' },
];

const LEGACY_DECISION_OPTIONS: CardInput['options'] = [
  { id: 'approved', label: 'Allow once', kind: 'allow_once' },
  { id: 'approved_for_session', label: 'Allow for this Codex session', kind: 'allow_session' },
  { id: 'denied', label: 'Decline', kind: 'deny' },
  { id: 'abort', label: 'Decline and stop', kind: 'cancel' },
];

function pick(options: CardInput['options'], id: string, fallback: string): string {
  return options.some((option) => option.id === id) ? id : fallback;
}

const PERMISSION_LABELS: Record<string, string> = { network: 'Network', fileSystem: 'Files' };
const MAX_GRANT_LINES = 40;

/** Every leaf of a Codex permission request as one readable line, so the card shows exactly what Allow grants. */
function describePermissionGrant(requested: unknown): { lines: string[]; complete: boolean } {
  const lines: string[] = [];
  let complete = true;
  const add = (line: string): void => { if (lines.length < MAX_GRANT_LINES) lines.push(line); else complete = false; };
  const walk = (value: unknown, label: string, depth: number): void => {
    if (value === null || value === undefined) return;
    if (depth > 6) { complete = false; return; }
    if (Array.isArray(value)) {
      if (!value.length) add(`${label}: none`);
      for (const entry of value) walk(entry, label, depth + 1);
      return;
    }
    if (typeof value === 'object') {
      for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
        walk(entry, label ? `${label} ${key}` : (PERMISSION_LABELS[key] || key), depth + 1);
      }
      return;
    }
    // Shown exactly as Codex sent it. A value that is too long, has line breaks or control characters, or
    // starts or ends with spaces cannot be shown faithfully, so that request can only be declined.
    const text = String(value);
    if (text.length > 400 || text !== text.trim() || /[\u0000-\u001f\u007f]/.test(text)) complete = false;
    add(`${label}: ${text.slice(0, 400)}`);
  };
  walk(requested, '', 0);
  return { lines, complete };
}

function legacyDecision(optionId: string): any {
  const id = pick(LEGACY_DECISION_OPTIONS, optionId, 'abort');
  return id === 'denied' ? { denied: { rejection: 'Declined in Prometheus.' } } : id;
}

function commandText(value: unknown): string {
  return Array.isArray(value) ? value.map((part) => String(part)).join(' ') : short(value, 2000);
}

/**
 * Map one Codex server request to a Prometheus card plus the exact upstream
 * answer shape. Only Codex's own decisions are offered. Returns null for
 * requests this adapter does not understand (they are declined upstream).
 */
export function mapCodexServerRequest(method: string, params: any, fileChangePaths: Map<string, string[]> = new Map()): MappedCodexRequest | null {
  const p = params || {};
  switch (method) {
    case 'item/commandExecution/requestApproval':
      return {
        card: {
          kind: 'command',
          title: 'Codex wants to run a command',
          detail: {
            ...(p.command ? { command: short(p.command, 2000) } : {}),
            ...(p.cwd ? { cwd: short(p.cwd, 1000) } : {}),
            ...(p.reason ? { reason: short(p.reason, 1000) } : {}),
          },
          options: V2_DECISION_OPTIONS,
        },
        cancelOptionId: 'cancel',
        toResult: (answer) => ({ decision: pick(V2_DECISION_OPTIONS, answer.optionId, 'cancel') }),
      };
    case 'item/fileChange/requestApproval': {
      const files = fileChangePaths.get(short(p.itemId, 300)) || [];
      return {
        card: {
          kind: 'file_change',
          title: 'Codex wants to change files',
          detail: {
            ...(files.length ? { files: files.slice(0, 50) } : {}),
            ...(p.reason ? { reason: short(p.reason, 1000) } : {}),
            ...(p.grantRoot ? { cwd: short(p.grantRoot, 1000) } : {}),
          },
          options: V2_DECISION_OPTIONS,
        },
        cancelOptionId: 'cancel',
        toResult: (answer) => ({ decision: pick(V2_DECISION_OPTIONS, answer.optionId, 'cancel') }),
      };
    }
    case 'execCommandApproval':
      return {
        card: {
          kind: 'command',
          title: 'Codex wants to run a command',
          detail: {
            command: commandText(p.command),
            ...(p.cwd ? { cwd: short(p.cwd, 1000) } : {}),
            ...(p.reason ? { reason: short(p.reason, 1000) } : {}),
          },
          options: LEGACY_DECISION_OPTIONS,
        },
        cancelOptionId: 'abort',
        toResult: (answer) => ({ decision: legacyDecision(answer.optionId) }),
      };
    case 'applyPatchApproval':
      return {
        card: {
          kind: 'file_change',
          title: 'Codex wants to change files',
          detail: {
            files: Object.keys(p.fileChanges || {}).slice(0, 50),
            ...(p.reason ? { reason: short(p.reason, 1000) } : {}),
          },
          options: LEGACY_DECISION_OPTIONS,
        },
        cancelOptionId: 'abort',
        toResult: (answer) => ({ decision: legacyDecision(answer.optionId) }),
      };
    case 'item/permissions/requestApproval': {
      const requested: any = {};
      if (p.permissions?.network) requested.network = p.permissions.network;
      if (p.permissions?.fileSystem) requested.fileSystem = p.permissions.fileSystem;
      // The card lists every item Allow would grant. A request too large to list in full can only be declined.
      const grant = describePermissionGrant(requested);
      const options: CardInput['options'] = [
        ...(grant.complete ? [
          { id: 'turn', label: 'Allow for this turn', kind: 'allow_once' as const },
          { id: 'session', label: 'Allow for this Codex session', kind: 'allow_session' as const },
        ] : []),
        { id: 'deny', label: 'Decline', kind: 'deny' },
      ];
      const asks = [requested.network ? 'network access' : '', requested.fileSystem ? 'extra file access' : ''].filter(Boolean).join(' and ')
        + (grant.complete ? '' : ' (too much to show in full, so it can only be declined here)');
      return {
        card: {
          kind: 'permissions',
          title: `Codex asks for ${asks || 'more permissions'}`,
          detail: {
            ...(p.cwd ? { cwd: short(p.cwd, 1000) } : {}),
            ...(p.reason ? { reason: short(p.reason, 1000) } : {}),
            grants: grant.lines,
            raw: requested,
          },
          options,
        },
        cancelOptionId: 'deny',
        // Codex's own sandbox grant, scoped by Codex. Nothing is recorded in Prometheus.
        toResult: (answer) => answer.optionId === 'turn' || answer.optionId === 'session'
          ? { permissions: requested, scope: answer.optionId }
          : { permissions: {}, scope: 'turn' },
      };
    }
    case 'item/tool/requestUserInput': {
      const questions = (Array.isArray(p.questions) ? p.questions : []).slice(0, 10).map((q: any) => ({
        id: short(q?.id, 200),
        prompt: [short(q?.header, 200), short(q?.question, 2000)].filter(Boolean).join(': '),
        ...(Array.isArray(q?.options) && q.options.length
          ? { options: q.options.slice(0, 20).map((o: any) => ({ id: short(o?.label, 200), label: [short(o?.label, 200), short(o?.description, 300)].filter(Boolean).join(' - ') })) }
          : {}),
      })).filter((q: any) => q.id);
      return {
        card: {
          kind: 'question',
          title: 'Codex has a question',
          detail: { questions },
          options: [
            { id: 'submit', label: 'Send answer', kind: 'answer' },
            { id: 'skip', label: 'Skip', kind: 'cancel' },
          ],
        },
        cancelOptionId: 'skip',
        toResult: (answer) => {
          const answers: Record<string, { answers: string[] }> = {};
          if (answer.optionId === 'submit') {
            for (const q of questions) {
              const given = answer.answers?.[q.id];
              if (Array.isArray(given) && given.length) answers[q.id] = { answers: given.map((v) => String(v)) };
            }
          }
          return { answers };
        },
      };
    }
    case 'mcpServer/elicitation/request': {
      const mode = String(p.mode || '');
      const properties = mode === 'form' && p.requestedSchema?.properties && typeof p.requestedSchema.properties === 'object'
        ? Object.entries(p.requestedSchema.properties as Record<string, any>).slice(0, 10)
        : [];
      if (mode !== 'url' && mode !== 'form') return null;
      const questions = properties.map(([key, schema]) => {
        const values: string[] = Array.isArray(schema?.enum) ? schema.enum.map(String)
          : schema?.type === 'boolean' ? ['true', 'false'] : [];
        return {
          id: short(key, 200),
          prompt: short(schema?.title || schema?.description || key, 500),
          ...(values.length ? { options: values.slice(0, 20).map((v) => ({ id: v, label: v })) } : {}),
        };
      });
      return {
        card: {
          kind: 'question',
          title: `${short(p.serverName, 80) || 'A Codex tool'} asks for input`,
          detail: {
            reason: short(p.message, 2000),
            ...(mode === 'url' ? { command: short(p.url, 2000) } : {}),
            ...(questions.length ? { questions } : {}),
          },
          options: [
            { id: 'accept', label: mode === 'url' ? 'Done' : 'Send', kind: 'answer' },
            { id: 'decline', label: 'Decline', kind: 'deny' },
            { id: 'cancel', label: 'Cancel', kind: 'cancel' },
          ],
        },
        cancelOptionId: 'cancel',
        toResult: (answer) => {
          const action = ['accept', 'decline', 'cancel'].includes(answer.optionId) ? answer.optionId : 'cancel';
          if (action !== 'accept' || mode !== 'form') return { action, content: null, _meta: null };
          const content: Record<string, unknown> = {};
          for (const [key, schema] of properties) {
            const raw = answer.answers?.[key]?.[0];
            if (raw === undefined) continue;
            content[key] = schema?.type === 'boolean' ? raw === 'true'
              : (schema?.type === 'number' || schema?.type === 'integer') ? Number(raw) : raw;
          }
          return { action, content, _meta: null };
        },
      };
    }
    default:
      return null;
  }
}
